triggers.encounter_search_insert:
CREATE TRIGGER encounter_search_insert AFTER INSERT ON encounters BEGIN
    INSERT INTO encounter_search(encounter_id, narrative) VALUES(new.id, new.narrative);
END

triggers.encounter_search_update:
CREATE TRIGGER encounter_search_update AFTER UPDATE ON encounters BEGIN
    DELETE FROM encounter_search WHERE encounter_id = old.id;
    INSERT INTO encounter_search(encounter_id, narrative) VALUES(new.id, new.narrative);
END

triggers.encounter_search_delete:
CREATE TRIGGER encounter_search_delete AFTER DELETE ON encounters BEGIN
    DELETE FROM encounter_search WHERE encounter_id = old.id;
END

triggers.confirmed_proposal_no_update:
CREATE TRIGGER confirmed_proposal_no_update BEFORE UPDATE ON proposals WHEN EXISTS (
    SELECT 1 FROM doctor_confirmations WHERE proposal_id=old.id
) BEGIN SELECT RAISE(ABORT, 'create a new proposal version'); END

triggers.relationship_roles:
CREATE TRIGGER relationship_roles BEFORE INSERT ON care_relationships BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1 FROM users WHERE id=new.doctor_id AND role='doctor' AND disabled=0
    ) THEN RAISE(ABORT, 'active doctor required') END;
END

triggers.patient_user_role:
CREATE TRIGGER patient_user_role BEFORE UPDATE OF user_id ON patients WHEN new.user_id IS NOT NULL BEGIN
    SELECT CASE WHEN NOT EXISTS (
        SELECT 1 FROM users WHERE id=new.user_id AND role='patient' AND disabled=0
    ) THEN RAISE(ABORT, 'active patient required') END;
END

triggers.decision_proposal_no_update:
CREATE TRIGGER decision_proposal_no_update BEFORE UPDATE ON proposals WHEN EXISTS (
    SELECT 1 FROM decision_drafts WHERE proposal_id=old.id
) BEGIN SELECT RAISE(ABORT, 'create a new decision version'); END

triggers.decision_proposal_no_delete:
CREATE TRIGGER decision_proposal_no_delete BEFORE DELETE ON proposals WHEN EXISTS (
    SELECT 1 FROM decision_drafts WHERE proposal_id=old.id
) BEGIN SELECT RAISE(ABORT, 'immutable decision proposal'); END

triggers.attempts_immutable_update:
CREATE TRIGGER attempts_immutable_update BEFORE UPDATE ON outbox_attempts BEGIN
